#!/usr/bin/env bash
# Self-contained Linux8c preflight. Invoke from the task checkout root.
set -uo pipefail
export RUSTC_WRAPPER= CARGO_BUILD_RUSTC_WRAPPER= CARGO_BUILD_JOBS=8
while IFS= read -r name; do unset "$name"; done < <(compgen -A variable MC_)
scratch=target/scratch/s4-preflight
mkdir -p "$scratch"
python3 - <<'S4_PAYLOAD'
import base64,hashlib,json,zlib
from pathlib import Path
payload=json.loads(zlib.decompress(base64.b64decode("")))
root=Path('target/scratch/s4-preflight')
for name,content in payload.items():
    path=root/name
    path.write_text(content)
    print('PREFLIGHT INPUT '+name+' sha256='+hashlib.sha256(path.read_bytes()).hexdigest(),flush=True)
S4_PAYLOAD

failure=0
baseline=0
summary="$scratch/summary.txt"
: >"$summary"
run() {
  local name=$1
  shift
  echo "=== S4 PREFLIGHT STEP $name"
  "$@" 2>&1 | tee "$scratch/$name.log"
  local code=${PIPESTATUS[0]}
  echo "=== S4 PREFLIGHT RESULT $name $code"
  printf '%s %s\n' "$name" "$code" >>"$summary"
  if [ "$code" -ne 0 ]; then failure=1; fi
  return "$code"
}
cargo --version
rustc --version
python3 --version
git rev-parse HEAD
git status --short
run fmt cargo fmt --all --check || baseline=1
run all-targets cargo check -p mc-module -p mc-store --all-targets || baseline=1
run source-cases cargo test -p mc-module --lib ancestor_acks:: -- --nocapture --test-threads=1 || baseline=1
run stack25 cargo test -p mc-module --lib stack25_delayed_acknowledgements_keep_publication_source_identities -- --nocapture --test-threads=1 || baseline=1
run campaign-replays env -u MC_S4_REPLAY_SEED cargo test -p mc-module --lib s4_replays_the_remaining_campaign_failures -- --nocapture --test-threads=1 || baseline=1
run f01 cargo test -p mc-module --lib final_f01 -- --nocapture --test-threads=1 || baseline=1
run f01-paired cargo test -p mc-module --lib final_same_ordinal_branches -- --nocapture --test-threads=1 || baseline=1
run production-revisit-timing python3 "$scratch/s4-preflight-instrument.py" perf || baseline=1
if [ "$baseline" -eq 0 ]; then
  run final-anchors python3 "$scratch/s4-final-fix-mutations.py" --anchors
  final_anchors=$?
  run ancestor-anchors python3 "$scratch/s4-ancestor-ack-mutations.py" --anchors
  ancestor_anchors=$?
  if [ "$final_anchors" -eq 0 ]; then
    run final-controls python3 "$scratch/s4-final-fix-mutations.py" || true
  fi
  if [ "$ancestor_anchors" -eq 0 ]; then
    run ancestor-controls python3 "$scratch/s4-ancestor-ack-mutations.py" || true
  fi
  run own-lib env -u MC_REVIEW_S4FINAL MC_S4FINAL_PROFILE=Broca MC_S4FINAL_RETENTION_MASTER_SEED=13174017127720468071 python3 "$scratch/s4-preflight-instrument.py" suite || true
else
  echo 'SKIPPED proofs and full sweep because a required baseline step failed.'
fi
python3 - <<'S4_SUMMARY'
from pathlib import Path
print('=== S4 PREFLIGHT SUMMARY')
print(Path('target/scratch/s4-preflight/summary.txt').read_text(),end='')
S4_SUMMARY
echo "=== S4 PREFLIGHT FINISHED $failure"
exit "$failure"
